const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Manitoba, Canada geometry
  var manitoba = ee.Geometry.Polygon([
    [-102.5, 60.0], // NW
    [-89.0, 60.0],  // NE
    [-89.0, 49.0],  // SE
    [-102.5, 49.0], // SW
    [-102.5, 60.0]  // Close
  ]);

  // 2. Define date: August 3, 2025
  var startDate = '2025-08-03';
  var endDate = '2025-08-04'; // Exclusive

  // 3. Try MODIS Active Fire data first
  var modisFires = ee.ImageCollection('MODIS/006/MCD14DL')
    .filterDate(startDate, endDate)
    .filterBounds(manitoba);

  var modisCount = modisFires.size();
  var modisCountVal = modisCount.getInfo();

  console.log('MODIS Fire Detections (2025-08-03):', modisCountVal, 'images');

  // 4. Check if MODIS has data, if not try VIIRS
  var fireCollection;
  var collectionName;

  if (modisCountVal > 0) {
    fireCollection = modisFires;
    collectionName = 'MODIS';
  } else {
    // Try VIIRS
    var viirsFires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGMT')
      .filterDate(startDate, endDate)
      .filterBounds(manitoba);

    var viirsCount = viirsFires.size();
    var viirsCountVal = viirsCount.getInfo();

    console.log('VIIRS Fire Detections (2025-08-03):', viirsCountVal, 'images');

    if (viirsCountVal > 0) {
      fireCollection = viirsFires;
      collectionName = 'VIIRS';
    } else {
      console.log('No fire detection data found for 2025-08-03');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Get the first image (should be only one for a single day)
  var fireImage = fireCollection.first();

  // 6. Count fire detections
  // For MODIS: use 'MaxFRP' or 'confidence' band (non-zero values indicate fires)
  // For VIIRS: use 'T21' or 'confidence' band
  var fireBand = (collectionName === 'MODIS') ? 'confidence' : 'confidence';

  // Create a mask for fire pixels (confidence > 0 for MODIS/VIIRS)
  var fireMask = fireImage.select(fireBand).gt(0);

  // Count fire pixels
  var fireStats = fireMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: manitoba,
    scale: 1000,
    maxPixels: 1e9
  });

  var fireCount = fireStats.get(fireBand);
  var fireCountVal = fireCount.getInfo();

  console.log(collectionName, 'Fire Count:', fireCountVal);

  // 7. Validation and final answer
  if (fireCountVal === null || fireCountVal === undefined || 
      isNaN(fireCountVal) || fireCountVal < 0) {
    console.log('Invalid fire count result');
    console.log('<answer>C3</answer>');
  } else if (fireCountVal === 0) {
    console.log('No fire pixels detected');
    console.log('<answer>B</answer>'); // Not more than 30 fires
  } else if (fireCountVal > 30) {
    console.log('Fire count > 30');
    console.log('<answer>A</answer>');
  } else {
    console.log('Fire count <= 30');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
